/* 删除屏幕根对象会递归删除其子控件；活动屏幕的安全切换由辅助函数处理。 */
void ui_screen1_screen_destroy(void)
{
    if (aidogui_ui.screen1.root != NULL) {
        _ui_screen_destroy(&aidogui_ui.screen1.root);
        aidogui_ui.screen1.root = NULL;
    }
}

/* 仅用于已离开的屏幕：保留根对象，子控件的 DELETE 回调会清空各自句柄。 */
void ui_screen1_screen_clean(void)
{
    if (aidogui_ui.screen1.root == NULL || !lv_obj_is_valid(aidogui_ui.screen1.root)) return;
    ui_screen1_content_ready = false;
    ui_screen1_cleaning = true;
    lv_obj_clean(aidogui_ui.screen1.root);
    ui_screen1_cleaning = false;
}

